('kobe-014', 'ja', '甲南大学', '神戸市東灘区岡本8-9-1', '《土砂災害時》原則、土砂災害警戒区域外（本山第二小学校）へ避難。ただし、警戒区域外への避難が困難な方や余裕のない場合は状況により利用可'),
