('kobe-014', 'ko', '고난 대학', '고베시히가시나다구오카모토8-9-1', '[토사재해] 원칙적으로 경계구역 밖(모토야마 다이니 초등학교)으로 대피하십시오. 다만 구역 밖 대피가 어렵거나 여유가 없는 경우 상황에 따라 이용할 수 있습니다.'),
